quests[7837] = { id = 7837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Runenstoff", progress = "Seid gegrüßt, {name}! Wir benötigen auch weiterhin noch Runenstoff. Zusätzliche Mittel sind daher jederzeit willkommen, solltet Ihr welche entbehren können. Liefert Ihr uns eine weitere Spende von 20 Stück Runenstoff, so werde ich dafür sorgen, dass Ihr die gebührende Anerkennung für Eure anhaltenden Bemühungen gegenüber den Dunkelspeertrollen erhaltet.\n\nWann auch immer Ihr die erforderte Menge abgeben könnt, ich werde sie jederzeit entgegennehmen.", completion = "{name} - ohne Helden, die sich wie Ihr für die Trolle der Dunkelspeere einsetzen, müssten wir so einiges in Kauf nehmen. Danke für Eure redlichen Bemühungen!" }
quests[7838] = { id = 7838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister der Arena", progress = "Aye, Landratte! Bringt mir 12 Schmuckstücke des hiesigen Meisters der Arena und Ihr seid der neue Großmeister der Arena der Gurubashi! Arrrr!", completion = "Ihr habt viel Blut in der Arena vergossen! Ich bin stolz darauf, Euch hiermit zum Großmeister der Arena zu ernennen!" }
quests[7839] = { id = 7839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schläger der Blutfratzen", description = "Der Blutfratzenabschaum ist in unser Dorf eingedrungen und hat mein Werkzeug gestohlen! Ich habe zwar Ersatz, aber das Set, das sie mir geraubt haben, war das Geschenk eines gutherzigen Gnoms, der mir als junger Orc das Leben gerettet hat.\n\nIch möchte dieses Werkzeug wieder haben, {name} - es bedeutet mir ungeheuer viel.\n\nMarkhor berichtete, dass die Werkzeuge nahe der Tempel von Agol'watha und Shaol'watha gesichtet wurden.\n\nDiese Tempel liegen im Nordosten des Hinterlands.\n\nFindet meine Werkzeuge!", sourceObjective = "Schmied Aschenbaum aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr seine verlorenen Werkzeuge ausfindig macht und dann zu ihm zurückkehrt.\n\nIhr erinnert Euch an Schmied Aschenbaums Worte, dass die Werkzeuge möglicherweise bei einem der Tempel der Blutfratzen zu finden seien, im Nordosten des Hinterlands. Ihr solltet auch den Lauerfels absuchen.", progress = "Nehmt Euch vor den Trollen der Vilebranch dieser Gegend in Acht, {name}. Sie sind unbarmherziger, mörderischer Abschaum.", completion = "Mein Werkzeug! Ihr habt es gefunden! Was für ein glorreicher Tag! Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[7840] = { id = 7840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lards vergessene Brotzeit", description = "Lard Picknick gemacht hat, an geheimen Geheimplatz, als hässlicher, fieser Blutfratzentroll Lard mit großem Stock geschlagen hat. Lard zurück ins Dorf der Bruchhauer gerannt sein, aber Lard Brotzeit vergessen hat. Lard hungrig. Ihr vielleicht zurück gehen zu geheimen Geheimplatz und holen Brotzeit von Lard? Lard hat Angst. Gehen Norden! Insel dort im Norden seien geheimer Geheimplatz.", sourceObjective = "Lard aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr Lards Brotzeit wieder findet. Kehrt nach Erfüllung dieser Aufgabe zu ihm zurück.\n\nLard erwähnte, dass er es auf der Insel im Norden vergessen habe. Achtet auf die Trolle der Blutfratzen.", progress = "<Lard streicht sich über seinen riesigen Bauch.>\n\nLard so hungrig.", completion = "<Lard nimmt die riesige Fleischkeule von Euch und stopft sie sich in den Mund.>\n\nErste Sahne! Schön'n Dank.\n\nLard Euch machen tollen Picknickkorb für helfen Lard.", sourceObjectiveStatus = "unverified-source-field" }
quests[7841] = { id = 7841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Botschaft an die Wildhämmer", description = "Die Wildhämmer fangen Geschäfte mit unseren Feinden an, Mann, schmieden neue Bündnisse. Diesmal sind es die Hochelfen, Mann.\n\n<Otho spuckt.>\n\nWir werden diesen Wildhammerzwergen wohl 'ne Botschaft überbringen müssen - 'ne Botschaft geschrieben mit dem Blut unserer Feinde. Tötet alle Hochtalelfen, alle die Euch über den Weg laufen, klar? Un' lasst ihre Leichen als Warnung zurück.\n\nVerscherzt es Euch niemals mit den Trollen!", sourceObjective = "Otho Moji'ko aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr 5 Hochtalkundschafterinnen, 8 Hochtalspäher, 2 Hochtalschützen und 5 Hochtalwaldläuferinnen tötet. Kehrt nach vollendeten Taten zu ihm zurück.\n\nIhr findet die Hochtalelfen bei der Jagdhütte von Quel'Danil im Nordwesten des Hinterlands.", completion = "Sieht ganz so aus, als ob die Revantusk nun auch neue Verbündete haben, Mann. Ihr wart gründlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[7842] = { id = 7842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine weitere Botschaft an die Wildhämmer", description = "Man sagt, dass die Wildhämmer den Greifen so nahe stehen wie die Trolle ihren Gefährten. Widerlich, aber wir können das zu unserem Vorteil nutzen, Mann. Wir senden ihnen eine weitere Botschaft.\n\nTötet alle Greifen, die Ihr im Hinterland seht und sammelt eine lange elegante Feder ein. Daraus machen wir dann die letzte Botschaft.", sourceObjective = "Otho Moji'ko aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr ihm 1 lange elegante Feder von Greifen besorgt, die das Hinterland bewohnen. Kehrt mit der Feder zu ihm zurück.\n\nEs ist bekannt, dass Greifen überall im Hinterland zu finden sind.", progress = "Die letzte Botschaft wird ihnen eine Heidenangst einjagen... oder sie verdammt wütend machen.", completion = "Oh Mann, das wird richtig gut werden. Nur noch ein Schritt und die Wildhammer werden sehen, dass sie es nicht mit den Trollen aufnehmen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[7843] = { id = 7843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Botschaft an die Wildhämmer", description = "<Otho überreicht Euch einen langen, blutverschmierten Speer, den mehrere Greifenfedern umhüllen.>\n\nNehmt den hier, Mann. Geht damit zum Nistgipfel, zum toten Stadtzentrum beim Brunnen. Platziert ihn dort! Rammt ihn richtig in den Boden und zeigt diesen Zwergen, dass die Trolle es ernst meinen! Kommt danach zu mir zurück... hoffentlich noch in einem Stück.", sourceObjective = "Otho Moji'ko aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr zum Nistgipfel im Westen des Hinterlands reist und die letzte Botschaft an die Wildhämmer beim Brunnen im Stadtzentrum platziert. Kehrt nach Vollendung der Aufgabe zu ihm zurück.\n\nHütet Euch vor zornigen Wildhammerzwergen und niederträchtigen Mitgliedern der Allianz.", progress = "Was wartet Ihr noch, Mann?", completion = "Ich wünschte, ich wär' dort gewesen, hätt' ihre Gesichter gesehen, Mann. Packen sie zusammen? Hau'n ab?\n\nKlasse Arbeit, {name}. Wirklich gut. Otho entlohnt Euch mit großem Mojo.", sourceObjectiveStatus = "unverified-source-field" }
quests[7844] = { id = 7844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kannibalistische Vettern", description = "Drei verschiedene Trollstämme bewohnen das Hinterland, {name}. So viel zu den Gemeinsamkeiten der Stämme: Wir sind alle Trolle und wir leben im Hinterland.\n\nDie Blutfratzen sind eine verkommene Bande, die sich an anderen Trollen und Humanoiden nährt.\n\nWäre Zul'jin hier, hätte er sie alle mit einem einzigen Faustschlag niedergeschmettert - ach, Zul'jin ist noch immer nicht zurückgekehrt und wir sind uns selbst überlassen.\n\nEs liegt nun an Euch diese Gegend zu säubern!", sourceObjective = "Mystikerin Yayo'jin aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr 6 Skalpierer der Blutfratzen und 2 Sterndeuter der Blutfratzen tötet. Kehrt nach Vollendung dieser Aufgabe zu ihr zurück.\n\nYayo'jin deutete an, dass man diese Trolle nahe der Tempel von Shaol'watha und Agol'watha finden könnte. Sie liegen im Nordosten des Hinterlands.", completion = "Gut gemacht, {class}. Zul'jin selbst hätte es nicht besser machen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[7845] = { id = 7845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Entführung des Ältesten Stumpfhauer", description = "Mein Gefährte wurde von den wilden Blutfratzen bei einem dreisten Überfall um Mitternacht verschleppt. Unsere Spione haben mir berichtet, dass er noch am Leben ist und hoch oben in Jintha'Alor gefangen gehalten wird. Man sagt, dass die üble Priesterin Hexx ihn als Opfer für den gesichtslosen Blutgott Hakkar vorbereiten lässt.\n\nIhr müsst ihn retten, {name}! Unser Dorf könnte einen so großen Verlust nicht verschmerzen.", sourceObjective = "Ura Stumpfhauer aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr ihren Gefährten, den Ältesten Stumpfhauer, aus Jintha'Alor befreit.\n\nMan sagte Euch, dass er hoch oben in Jintha'Alor gefangen gehalten wird - der Hauptstadt der Blutfratzen im Süden des Hinterlands.", completion = "Ihr müsst schnell handeln, {name}. Eure Anwesenheit hat bestimmt schon die Wachen alarmiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[7846] = { id = 7846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erlangt den Schlüssel!", description = "Der Schlüssel zu meinen Fesseln ist im Besitz von Hitah'ya der Bewahrerin. Sie hält sich in der nahegelegenen Höhle auf. Seid vorsichtig, {class}, sie wird äußerst gut bewacht.\n\nTötet sie und bringt dann den Schlüssel zurück, um meine Fesseln zu öffnen. Erst dann werde ich frei und in der Lage sein, nach Hause zurückzukehren.", sourceObjective = "Der Älteste Stumpfhauer in Jintha'Alor möchte, dass Ihr Hitah'ya die Bewahrerin tötet, um in den Besitz des Fesselnschlüssels zu kommen. Kehrt zum Ältesten Stumpfhauer zurück, wenn Ihr den Schlüssel habt.", progress = "Ihr müsst Euch beeilen!", completion = "Endlich frei! Danke, {name}. In Revantusk wird man von Euren Taten erzählen!", sourceObjectiveStatus = "unverified-source-field" }
quests[7847] = { id = 7847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Ura Stumpfhauer", description = "Kehrt zu meiner Gefährtin Ura Stumpfhauer ins Dorf der Bruchhauer zurück. Richtet ihr aus, dass ich heimkehren werde! Sie wird Euch sicherlich belohnen.", sourceObjective = "Der Älteste Stumpfhauer in Jintha'Alor möchte, dass Ihr Ura Stumpfhauer im Dorf der Bruchhauer die Neuigkeit von seiner Befreiung überbringt.", completion = "Ihr habt den Revantusk einen großen Dienst erwiesen, {name}! Wir schulden Euch sehr viel Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[7848] = { id = 7848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abstimmung mit dem Kern", description = "Risse und Abgründe bilden sich um uns herum und kollabieren wieder, {race}. Keine zwei Schritte von mir entfernt, ist ein Riss, der hinab in die tiefsten Tiefen des Schwarzfels führt, bis in die Ruhestätte des Feuerfürsten.\n\nÜberrascht? Wie bedauerlich... Ihr sterblichen Völker versteht einfach nichts, was Ihr nicht sehen, anfassen oder fühlen könnt.\n\nIch versichere Euch, das Portal ist da und es ist passierbar.\n\nHabe ich Euer Interesse geweckt? Eine Anpassung ist simpel. Begebt Euch in die Schwarzfelstiefen und findet ein Kernfragment. Bringt es zu mir zurück und ich werde Eure Essenz mit dem Portal abstimmen.", sourceObjective = "Begebt Euch zum Portal in den Schwarzfelstiefen, das in den geschmolzenen Kern führt, und findet ein Kernfragment. Kehrt mit dem Fragment zu Lothos Felsspalter am Schwarzfels zurück.", progress = "Ihr müsst Eure Seele mit dem geschmolzenen Kern abstimmen, bevor Ihr Zugang erhaltet.", completion = "Ich bin jetzt in der Lage, Euch zum geschmolzenen Kern zu transportieren. Ihr braucht nur zu fragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7849] = { id = 7849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die getrennten Brüder", description = "Wie viele in unserem Dorf, habe auch ich einen Nahestehenden verloren. Ach, es war mein Zwillingsbruder Malkhor - er wurde beim selben Überfall wie Stumpfhauers Gefährte von den Blutfratzen verschleppt.\n\nDas Schicksal sollte ihn traurigerweise nicht vom Tod verschonen und er wurde schnell und brutal hingerichtet. Seine Überreste wurden an die Schlamme und Wölfe der Blutfratzen verfüttert.\n\nWir können zwar nicht mehr sein Leben retten, aber es ist noch nicht zu spät, um seine Seele zu befreien. Bergt seine Überreste, {name}.", sourceObjective = "Jäger Markhor aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr die Überreste seines Zwillingsbruders bergt. Findet den Schädel und die Knochen des Jägers Malkhor und bringt sie zu Jäger Markhor zurück.\n\nMarkhor erwähnte, dass die Überreste seines Bruders an die Schlamme und Wölfe der Blutfratzen verfüttert wurden. Er sagte weiterhin, dass es in Jintha'Alor eine Grube mit Schlammen gibt, sowie einen Wolfsbau. Beide liegen in der Nähe der Tempelspitze.", progress = "Wenn Ihr seine Überreste geborgen habt, werde ich sie zu Yayo'jin bringen und sie für eine gebührliche Bestattung vorbereiten lassen.", completion = "Mein geliebter Bruder, wie sehr ich dich vermissen werde...\n\nDanke für Eure Hilfe, {name}. Ihr seid ein wahrer Held für mich.", sourceObjectiveStatus = "unverified-source-field" }
quests[7850] = { id = 7850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Gefäße", description = "Die Blutfratzen kämpfen mit übernatürlicher Wildheit. Dies liegt an der elenden Magie, die von der üblen Priesterin Hexx gewirkt wird.\n\nIhr werdet in ganz Jintha'Alor dunkle Gefäße mit besudeltem Blut finden. Die Gefäße verstrahlen die elende Magie des gesichtslosen Blutgottes, verleihen den Blutfratzen Macht und treiben sie zusätzlich in den Wahnsinn.\n\nStehlt diese Gefäße und bringt sie zu mir, damit ich sie von der Besudelung reinigen und letztendlich die Gewalt des Blutgottes zerschlagen kann.", sourceObjective = "Ura Stumpfhauer aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr Euch 5 Gefäße mit besudeltem Blut aus Jintha'Alor beschafft. Kehrt dann damit zu Ura Stumpfhauer zurück.", progress = "Seid beim Kampf mit den Vilebranch auf der Hut, {name}. Ihre Gedanken sind nicht klar - sie kämpfen bis zum Tod.", completion = "Die dunkle Energie, die die Vilebranch gefügig macht, wurde aufgelöst - für's Erste. Wir müssen bei unserem Kampf gegen das Böse stets wachsam bleiben, denn auch wenn die üble Priesterin vernichtet wurde, so wird doch bald ein anderer ihren Platz einnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7861] = { id = 7861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Üble Priesterin Hexx und ihre Diener", description = "Der üblen Priesterin Hexx und ihren Dienern soll im Namen von Ura Stumpfhauer Gerechtigkeit widerfahren!\n\nWer auch immer die üble Priesterin Hexx und alle ihre Aman'zasiwachen vernichten möge, soll eine bedeutende Entlohnung erhalten.", sourceObjective = "Ihr habt die Anweisung erhalten die üble Priesterin Hexx und 5 Aman'zasiwachen der Blutfratzen zu töten. Habt Ihr Eure Aufgabe erfüllt, so sprecht mit Ura Stumpfhauer aus dem Dorf der Bruchhauer im Hinterland.\n\nDie üble Priesterin Hexx und die Aman'zasiwachen halten sich hoch oben in Jintha'Alor im Hinterland auf.", completion = "Das war in der Tat ein lähmender Schlag für die Vilebranch. Ihr sollt reichlich entlohnt werden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[7862] = { id = 7862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offener Posten: Wachbefehlshaber der Bruchhauer", description = "Mit dem Verlust von Malkhor ist auch wieder der Posten des Wachbefehlshabers der Bruchhauer unbesetzt. Sollte es Euch interessieren Befehlshaber der Bruchhauerwachen zu werden, so erfüllt die folgenden Aufgaben und reicht Eure Bewerbung bei Ura Stumpfhauer ein:\n\nRottet die Berserker der Blutfratzen aus.\n\nRottet die Schattenjäger der Blutfratzen aus.\n\nRottet die Bluttrinker der Blutfratzen aus.\n\nRottet die Seelenfresser der Blutfratzen aus.", sourceObjective = "Ihr wurdet mit der Vernichtung von 5 Berserkern der Blutfratzen, 3 Schattenjägern der Blutfratzen, 3 Bluttrinkern der Blutfratzen und 2 Seelenfressern der Blutfratzen beauftragt.\n\nKehrt nach Beendigung dieser Aufgabe zu Ura Stumpfhauer ins Dorf der Bruchhauer im Hinterland zurück.", completion = "Ihr seid wirklich ein würdiger Kandidat für den neuen Posten, {name}. Nehmt dieses Schmuckstück als Zeichen unserer Anerkennung für Eure harte Arbeit. Ich werde mir sämtliche Bewerbungen nächstes Jahr durchsehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7863] = { id = 7863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basisüberlebenspaket der Schildwache" }
quests[7864] = { id = 7864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standardüberlebenspaket der Schildwache" }
quests[7865] = { id = 7865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbessertes Überlebenspaket der Schildwache", sourceObjective = "Ihr habt zweifellos begonnen, Euch bei uns als würdig zu erweisen, {name}. Bitte, nehmt dieses Überlebenspaket als Gegenleistung an! Ihr findet darin Rationen und Verbände, die nur innerhalb der Warsongschlucht verwendet werden können.\n\nBewährt Ihr Euch noch weiter in der Schlucht, werdet Ihr auch mehr dieser Gegenstände erwerben können. Ihr erhaltet die Rationen, wenn unsere Einstellung Euch gegenüber freundlich ist, sowie Verbände, wenn Ihr unser Wohlwollen erlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[7866] = { id = 7866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basisüberlebenspaket der Vorhut" }
quests[7867] = { id = 7867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standardüberlebenspaket der Vorhut" }
quests[7868] = { id = 7868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbessertes Überlebenspaket der Vorhut", sourceObjective = "Ihr habt zweifellos begonnen, Euch bei uns als würdig zu erweisen, {name}. Bitte, nehmt dieses Überlebenspaket als Gegenleistung an! Ihr findet darin Rationen und Verbände, die nur innerhalb der Warsongschlucht verwendet werden können.\n\nBewährt Ihr Euch noch weiter in der Schlucht, werdet Ihr auch mehr dieser Gegenstände erwerben können. Ihr erhaltet die Rationen, wenn unsere Einstellung Euch gegenüber freundlich ist, sowie Verbände, wenn Ihr unser Wohlwollen erlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[7871] = { id = 7871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegt die Eindringlinge!", description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, <junger/junge:c> {class}. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Kriegshymnenschlucht und verteidigt die Feste der Silberschwingen. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, {name} und ich werde Euch belohnen.", sourceObjective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt zur Schildwache Weltensang am Hain der Silberschwingen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7872] = { id = 7872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegt die Eindringlinge!", description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, <junger/junge:c> {class}. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Kriegshymnenschlucht und verteidigt die Feste der Silberschwingen. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, {name} und ich werde Euch belohnen.", sourceObjective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt zur Schildwache Weltensang am Hain der Silberschwingen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7873] = { id = 7873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegt die Eindringlinge!", description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, <junger/junge:c> {class}. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Kriegshymnenschlucht und verteidigt die Feste der Silberschwingen. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, {name} und ich werde Euch belohnen.", sourceObjective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt zur Schildwache Weltensang am Hain der Silberschwingen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7874] = { id = 7874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt die Eindringlinge der Silberschwingen", description = "Die Wildnis des Eschentals wird sich der Macht der Horde ergeben, {race}. Nichts, was die Silberschwingen tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche unseren Fortschritt zu behindern, zunichte macht. Zerstört die Schildwachen der Silberschwingen und erlangt ein Ehrenabzeichen des Kriegshymnenklans. Kehrt zu mir zurück {name}, wenn Ihr im Besitz eines Ehrenabzeichens seid und ich werde Euch belohnen.", sourceObjective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt anschließend zu Hauptmann Schädelbrecher im Stützpunkt Mor'shan zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7875] = { id = 7875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt die Eindringlinge der Silberschwingen", description = "Die Wildnis des Eschentals wird sich der Macht der Horde ergeben, {race}. Nichts, was die Silberschwingen tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche unseren Fortschritt zu behindern, zunichte macht. Zerstört die Schildwachen der Silberschwingen und erlangt ein Ehrenabzeichen des Kriegshymnenklans. Kehrt zu mir zurück {name}, wenn Ihr im Besitz eines Ehrenabzeichens seid und ich werde Euch belohnen.", sourceObjective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt anschließend zu Hauptmann Schädelbrecher im Stützpunkt Mor'shan zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7876] = { id = 7876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt die Eindringlinge der Silberschwingen", description = "Die Wildnis des Eschentals wird sich der Macht der Horde ergeben, {race}. Nichts, was die Silberschwingen tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche unseren Fortschritt zu behindern, zunichte macht. Zerstört die Schildwachen der Silberschwingen und erlangt ein Ehrenabzeichen des Kriegshymnenklans. Kehrt zu mir zurück {name}, wenn Ihr im Besitz eines Ehrenabzeichens seid und ich werde Euch belohnen.", sourceObjective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt anschließend zu Hauptmann Schädelbrecher im Stützpunkt Mor'shan zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7877] = { id = 7877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatz der Shen'dralar", description = "In der Bücherei, dem Athenaeum, werdet Ihr unter dem Treppenaufgang eine uralte Truhe finden. Nehmt Euch aus der Truhe was Ihr wollt.", sourceObjective = "Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!", completion = "Ihr öffnet die Truhe und findet...", sourceObjectiveStatus = "unverified-source-field" }
quests[7881] = { id = 7881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jahrmarktsstiefel", progress = "Wir vom Dunkelmond-Jahrmarkt sind sehr viel zu Fuß unterwegs. Wir laufen von einer Attraktion zur nächsten... eigentlich werdet Ihr uns niemals während der Arbeit sitzen sehen! Es ist also nicht überraschend, dass wir viel Schuhwerk verschleißen! Wir brauchen Stiefel, die belastbar und gleichzeitig modisch sind. Geprägte Lederstiefel sind da genau das Richtige.\n\nHey! Ihr seid Lederer, macht mir ein Paar Geprägte Lederstiefel und ich gebe Euch für Eure Arbeit ein Los des Dunkelmond-Jahrmarkts.", completion = "Danke, {name}. Eine wirklich gute Verarbeitung! Euer handwerkliches Können ist erstklassig! Hier ist Euer Los... viel Spaß damit mein Herr." }
quests[7882] = { id = 7882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jahrmarktswämser", progress = "Unsere Arbeiter vom Jahrmarkt machen weitaus mehr als Dreck wegzufegen und Bolzen einzuschlagen! Sie helfen auch den Jahrmarkt auf Reisen zu bewachen und benötigen dafür stets robuste und rüstungsstarke Wämser.\n\nWenn Ihr etwas strapazierfähige Rüstung herstellt und zu mir bringt, dann werde ich dies sicherlich an die richtigen Leute weiterleiten. Ich werde Euch im Austausch dafür auch ein paar Lose des Dunkelmond-Jahrmarkts geben.", completion = "Ah, Ihr habt die Wämser. Wunderbar. Darf ich fragen welches Tierleder Ihr für die Herstellung verwendet habt? Die Nähte sind erstklassig verarbeitet worden und die Struktur des Leders scheint ebenfalls sehr robust. Ihr seid ein begabter Handwerker!\n\nDankeschön, {name}, hier sind Eure Lose." }
quests[7883] = { id = 7883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der größte Gnom der Welt!" }
quests[7884] = { id = 7884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Krokilisken-Junge und der bärtige Murloc", progress = "Yebb arbeitet an einer weiteren Attraktion für sein Kuriositätenkabinett. Es handelt sich dabei um eine nasse und sumpfige Behausung für einen Jungen, der von Krokilisken aufgezogen wurde und vielleicht auch für einen Murloc. Wir werden schöne, wasserdichte Beinkleider brauchen, damit  wir während dem Auf- und Abbauen nicht pitschnass werden. Schildkrötenschuppengamaschen würden sich dafür bestens eignen.\n\n{name}, könnt Ihr solche für uns anfertigen? Wenn ja, dann wird Euch ein dicker Stapel Lose des Dunkelmond-Jahrmarkts erwarten.", completion = "Klasse, Ihr habt sie hergestellt! Die werden ihren Zweck erfüllen... Ich hoffe nur, dass nicht ich es bin, der den Krokiliskenkäfig reinigen darf, wenn es soweit ist. Diese Viecher können ganz schön fies sein, findet Ihr nicht?\n\nHier Eure Lose, {name}.  Viel Spaß damit und auf dem Jahrmarkt!" }
quests[7885] = { id = 7885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rüstungssets", progress = "Es mag Euch vielleicht nicht bewusst sein, aber die Unterhaltung eines fahrenden Jahrmarkts ist kostspielig! Alles nutzt sich so schnell ab, es ist erstaunlich, dass wir überhaupt Gewinne machen.\n\nWegen all dieser versteckten Kosten, suchen wir immer nach Möglichkeiten, wie wir unsere Ausrüstung so günstig wie möglich instandhalten lassen können. Unsere Zelte reißen zum Beispiel regelmäßig, aber ich habe gemerkt, dass Lederrüstungssets gute Flicken abgeben. Könnt Ihr mir ein paar Rüstungssets besorgen? Das würde uns den Kauf von einigen neuen Zelten ersparen! Wenn Ihr uns damit aushelfen könntet, dann würde Euch eine Hand voller Lose des Dunkelmond-Jahrmarkts erwarten...", completion = "Sehr schön! Das wird uns weiterhelfen! Ich habe gerade einen Riss im Zelt dort drüben entdeckt und eines dieser Rüstungssets ist genau das, was ich zum Flicken brauchen kann!\n\nVielen Dank, {name}. Diese Rüstungssets werden uns eine Menge an Reparaturkosten einsparen. Hier sind die Lose - Ihr habt sie Euch verdient!" }
quests[7889] = { id = 7889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grober Gewichtsstein" }
quests[7890] = { id = 7890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwerer Schleifstein", progress = "Ich würde gerne einen Stab zwischen schweren Schleifsteinen befestigen und ihn dann über meinen Kopf stemmen, um mein Training zu verbessern. Es ist nicht einfach, aber man wird schließlich nicht durch bloßes Herumsitzen zur stärksten Frau der Welt - so wie ich es bin!\n\nKönnt Ihr mir helfen? Ich brauche mehr Schleifsteine - bringt mir ein paar und ich tausche sie gegen Lose des Dunkelmond-Jahrmarkts ein.", completion = "Ihr habt die Steine bekommen! Sie sind auch noch richtig schwer! Ich kann schon fühlen wie meine Muskeln anschwellen.  Danke {name}!\n\nHier, nehmt diese Lose - und achtet darauf nicht zu viele Süßigkeiten während des Jahrmarkts zu essen. Ein großer starker {class} wie ihr muss sich schließlich kämpferisch in Form halten!" }
quests[7891] = { id = 7891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grüne Eisenarmschienen", progress = "Ich arbeite an einem neuen Kostüm für später, wenn ich einmal meinen eigenen Stand als stärkste Frau der Welt habe! Ich suche gerade nach ein paar Armschienen, die ich tragen könnte. Sie dürfen nicht zu viel bedecken, da die Leute meine Muskeln sehen möchten, aber ich möchte trotzdem etwas Farbe ins Spiel bringen, versteht Ihr?\n\nWie wäre es mit grünen Eisenarmschienen, {name}? Könnt Ihr mir solche herstellen? Wenn ja, dann hätte ich einen ganzen Haufen Lose des Dunkelmond-Jahrmarkts für Euch.", completion = "Ja! Das sind genau die Richtigen! Sie haben so eine wunderschöne Farbe und lassen meine Arme ausreichend frei, damit man sehen kann wie stark ich bin! Perfekt!\n\nHier, {name}. Hier sind Eure Lose - amüsiert Euch schön!" }
quests[7892] = { id = 7892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großer schwarzer Streitkolben" }
quests[7893] = { id = 7893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rituale der Stärke", progress = "{name}, in meinem Bestreben die stärkste Frau der Welt zu werden, bin ich auf meinen Reisen bereits weit umher gekommen und habe geheime Trainingstechniken von Gewichthebern, Kraftgurus und uralten Handbüchern erlernt. Ich kenne verbotene Übungen, die  Schwache töten und Unerfahrene verkrüppeln könnten!\n\nDiese Leistung von Stärke und Konditionierung erfordert ein Training mit den schwersten aller Schleifsteine überhaupt. {name}, könnt Ihr mir diese Steine besorgen oder für mich herstellen? Ich würde Euch dafür auch Lose geben...", completion = "Ich danke Euch, {name}. Ich werde diese Steine bei einem kräftebringenden Ritual verwenden, das ich von einer uralten Schrifttafel im tiefsten Dschungel des Schlingendorntals erlernt habe.\n\nMan sagt, dass derjenige, die das heilige Ritual korrekt ausführt, die Stärke und Ausdauer von zehn Tauren besitzen wird!" }
quests[7894] = { id = 7894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kupfermodulator", progress = "Yebb arbeitet an einer neuen Attraktion für das Kuriositätenkabinett, eine, die die Leute vor Verwunderung und Erstaunen begeistern wird! Es wird allerdings eine Menge an Arbeit und bedeuten und viel Material benötigen...\n\nUnter anderem Kupfermodulatoren. Wir brauchen zahlreiche Modulatoren für die mechanischen Teile der Attraktion.  Bringt mir Kupfermodulatoren und ich werde sie gegen ein Los des Dunkelmond-Jahrmarkts einlösen.", completion = "Aha! Die Modulatoren! Herrlich!\n\nIch kann Euch zwar nicht genau sagen an was wir arbeiten, aber dies wird für dessen Konstruktion von unschätzbarem Wert sein. Ich stehe in Eurer Schuld, {name}, bitte, nehmt dieses Los des Dunkelmond-Jahrmarkts als Zeichen meiner Wertschätzung." }
quests[7895] = { id = 7895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surrendes bronzenes Dingsda", progress = "Mein neuer Stand wird etwas, das man sehen muss, ja! Etwas, das man sehen muss und... für ein paar Glückliche ist es auch etwas zum Anfassen!\n\nIch kann schon das mechanische Entzücken der surrenden kleinen Dingsdas hören und sehe schon die Kunden vor mir, wie sie näher an meinen Stand treten, um ihre Fähigkeiten zu testen!\n\nAh... jetzt brauche ich die Dingsdas selbst, um meinem Traum ein Stückchen näher zu kommen. Bitte, {name}, bringt mir surrende bronzene Dingsdas... und ein paar Lose des Dunkelmond-Jahrmarkts werden Euer sein!", completion = "Ihr habt die Dingsdas! Wunderbar! Ich kann schon jetzt das melodische Summen und Surren in meinem Kopf hören! Oh, wenn dieser Stand erst einmal fertig ist, dann wird er ein Weltwunder sein, das mich zeichnen wird!\n\nHier sind Eure Lose, {name}. Bitte amüsiert Euch auf dem Jahrmarkt!" }
quests[7896] = { id = 7896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grünes Feuerwerk", progress = "Wenn ich meinen Stand endlich fertig habe, möchte ich auch dafür werben! Was würde sich dafür schon besser eignen als Feuerwerk?\n\nNun, manch einer würde sagen, dass sich der Geruch eines Kessels, in dem die Köpfe unserer Feinde köcheln, besser zum Anziehen von Massen eignet, aber... wir sind eine gemischte Gesellschaft. Es muss also Feuerwerk sein!\n\nBringt mir grünes Feuerwerk, {name}, und ich werde Euch eine Hand voller Lose des Dunkelmond-Jahrmarkts geben.", completion = "Ihr habt das Feuerwerk. Wunderbare Arbeit, {name}! Ich kann nicht erwarten es zu zünden und damit allen zu sagen, dass mein Stand eröffnet ist! Ich muss noch warten, sogar noch ziemlich lange fürchte ich, aber... ich werde bereit sein, wenn ich bereit bin, richtig?\n\nHier sind die Lose, {name}. Viel Spaß!" }
quests[7897] = { id = 7897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mechanische Repariersets", progress = "Der hauptsächliche Grund, weshalb ich meinen Stand nicht eröffnen kann, ist... weil alles kaputt ist! Ich brauche mechanische Repariersets, um alles wieder herrichten zu können!\n\nKönnt Ihr mir diese Sets besorgen, {name}? Ich tausche sie gegen... Sets von Losen des Dunkelmond-Jahrmarkts. Was denkt Ihr?", completion = "Danke! Jetzt kann ich wieder für Ordnung sorgen.\n\nIch werde eine Menge Repariersets brauchen und oft bis spät in die Nacht arbeiten, um alles wieder zum Laufen bringen zu können.  Manchmal glaube ich, dass es besser wäre, wenn ich wieder zu meinen Wurzeln zurückkehren und meine Laufbahn als Kopfgeldjäger weiterverfolgen würde, aber... der Jahrmarkt tut mir gut.\n\nNehmt diese Lose, {name}, viel Spaß damit!" }
quests[7898] = { id = 7898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thoriumapparat", progress = "Yebb Nebblegear arbeitet wie ich an einer zukünftigen Attraktion. Nebb sagt, dass die Attraktion so aufregend ist, dass es Besucher aus der ganzen Welt anziehen wird...und uns alle sehr, sehr reich!\n\nEr meint, dass er Thoriumapparate für dieses Projekt benötigt und ich soll sie für ihn sammeln. Na, was sagt Ihr; {name}? Wisst Ihr, wo man Thoriumapparate bekommt? Solltet ihr Ingenieur sein, könntet Ihr dann welche herstellen? Wollt Ihr sie gegen Lose des Dunkelmond-Jahrmarkts einlösen?", completion = "Ah, vielen Dank {name}! Yebb wird sich über diese Apparate freuen. Ich weiß nicht, was er damit vorhat, aber Yebb ist ein cleverer kleiner Gnom. Er ist clever und vielleicht auch ein bisschen verschlagen...\n\nWenn er doch nur den Geschmack menschlichen Fleisches mögen würde, dann würde er einen großartigen Troll abgeben!\n\nHier {name}, Geschäft ist Geschäft! Diese Lose gehören Euch." }
quests[7899] = { id = 7899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine pelzige Tatzen", progress = "Will man eine große Masse herbeilocken, sollte man vor allem eines wissen: wie man mit kleinen Anreizen und Krimskrams ihr Interesse weckt! Könnt Ihr mir dabei helfen?\n\nIch brauche kleine pelzige Tatzen, die ich als Preise verwenden kann. Ihr könnt dergleichen von den Katzen des Brachlands oder der Dunkelküste erhalten...\n\nBringt mir ein paar Tatzen und ich tausche sie gegen ein Los des Dunkelmond-Jahrmarkts ein.", completion = "Großartig, Ihr habt sie! Wir können daraus Spielsachen und anderen Schnickschack herstellen und damit bei mehr und mehr Leuten Interesse für den Jahrmarkt wecken!\n\nHier ist Euer Los, {name}.  Ihr habt es Euch verdient!" }
quests[7900] = { id = 7900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerrissene Bärenpelze", progress = "Kinder lieben Spielsachen! Egal was für Kinder, ich habe herausgefunden, dass alle Kinder pelzige und kuschelige Spielsachen lieben, die aus zerrissenem Bärenpelz angefertigt wurden!\n\nIhr könnt diese Pelze von Bären aus Ashenvale oder Hillsbrad bekommen.  Bringt mir einen Haufen davon und verdient Euch damit eine Menge Lose des Dunkelmond-Jahrmarkts!", completion = "Schöne Pelze, {name}! Ich werde daraus eine Menge Kuscheltiere nähen lassen. Mit Hilfe von etwas Füllmaterial und Farbe, könnte daraus eines der begehrtesten Spielsachen in ganz Azeroth werden!\n\nLose? Ach ja, Euer Entgelt!  Hier sind sie!" }
quests[7901] = { id = 7901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiche buschige Schwänze", progress = "Es ist unglaublich was Leute so alles schätzen! Wie wäre es zum Beispiel mit einem Stock, an dem man einen weichen buschigen Schwanz hängt. Ihr und ich mögen nun denken, dass derartiges keinerlei Wert hat... aber verpasst man so einem Quatsch einen netten Namen wie \"Wilder Wuschelschwanz\" und packt das Ganze in eine hübsche Schachtel, dann erscheint es den Leuten plötzlich wertvoll. Aus Tand werden heiß begehrte Objekte!\n\nBesorgt mir ein paar weiche buschige Schwänze von Wölfen aus Desolace und dem Ödland, dann werde ich Euch dafür Lose des Dunkelmond-Jahrmarkts geben.", completion = "Gut gemacht, {name}! Diese buschigen Schwänze werden unseren Besuchern gefallen - und das bedeutet sogleich glückliche Besucher... Besucher, die ihren Freunden vom Jahrmarkt erzählen und somit für noch mehr Publikum sorgen!\n\nHier sind Eure Lose! Viel Spaß auf dem Dunkelmond-Jahrmarkt... und vergesst nicht Euren Freunden von uns zu erzählen!" }
quests[7902] = { id = 7902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farbenprächtige Federbüsche", progress = "Das Vorstellungsvermögen einer Person ist etwas Unglaubliches. Es kann aus einem kleinen Hügel einen riesigen Berg machen und aus einem harmlosen Schatten einen furchtbaren Alptraum!\n\nWir vom Dunkelmond-Jahrmarkt erwecken die Fantasien unserer Besucher zum Leben! Allerdings müssen wir uns manchmal schlaue Tricks einfallen lassen, um ihren Vorstellungen etwas auf die Sprünge zu helfen...\n\nIch brauche farbenprächtige Federbüsche für eine meiner Attraktionen. Ihr könnt sie von den Vögeln der etwas gefährlicheren Gegenden Azeroths bekommen. Bringt mir diese Federn und zahlreiche Lose werden Euer Eigen sein!", completion = "Ah, die Federn! Sie sind atemberaubend, findet Ihr nicht! Mit diesen Schönheiten dürfte das Entfachen der Fantasie ein einfaches sein!\n\nIhr leistet so wohltätige Arbeit, {name}. Das Leuchten in den Augen der Besucher, wenn sie unsere Attraktionen bestaunen, ist bereits ein hoher Lohn, aber bitte, nehmt auch diese Lose." }
quests[7903] = { id = 7903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Böse Fledermausaugen", progress = "Kommt es vor, dass Ihr spät in der Nacht in einer Höhle umherwandert und nach Abenteuern sucht? Ja? Wirklich? Nun, dann habt Ihr die gruseligen Fledermausaugen gesehen, die Euch von hoch oben anstarren und nur darauf warten, dass Ihr unachtsam werdet, damit sie Euch Euer Blut aussaugen können!\n\nEin schauriger Gedanke, nicht wahr? Natürlich - Fledermausaugen sind ohne Frage gruselig!\n\nKönnt Ihr mir ein paar böse Fledermausaugen besorgen, {name}? Ich brauche sie für... für etwas, das ich entwerfe. Etwas Gruseliges.\n\nIhr könnt sie von den Fledermäusen der östlichen Pestländer bekommen.", completion = "Großartig! Ihr habt die Augen! Ich hoffe die Jagd nach den Fledermäusen war furchterregend für Euch, denn wenn sie einen mutigen {class} wie Ihr es seid ängstigen konnten, dann werden diese Augen ganz sicher auch unseren Jahrmarktsbesuchern einen Schrecken einjagen können.\n\nNehmt diese Lose, {name}, danke für Eure Dienste." }
quests[7905] = { id = 7905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dunkelmond-Jahrmarkt", description = "Der Dunkelmond-Jahrmarkt kommt! Lasst Euch beim Besuch in Eurer Stadt nicht all die Wunder und Attraktionen entgehen!\n\nZögert nicht und Ihr werdet diesen Gutschein für kostenfreie Gewinnlose einlösen können! Bringt Euren Gutschein einfach zu Gelvas Rußgatter, der sich innerhalb des Jahrmarkts aufhält.\n\nMomentan hat der Jahrmarkt seine Zelte außerhalb von Goldhain im Wald von Elwynn aufgeschlagen. Lasst Euch diese Gelegenheit nicht entgehen! Heute ist Euer Tag!", sourceObjective = "Bringt den Gutschein zu Gelvas Rußgatter, der sich innerhalb des Dunkelmond-Jahrmarkts aufhält.", progress = "Ja, kann ich Euch vielleicht behilflich sein? Habt Ihr einen Gutschein zum Einlösen?", completion = "Willkommen beim Dunkelmond-Jahrmarkt! Dieser Gutschein ist gültig für FÜNF, ja, FÜNF Gewinnlose!\n\nHabt Ihr Gewinnlose angesammelt, dann werdet Ihr mit mir sprechen wollen, um sie gegen wertvolle Preise einzutauschen. Je mehr Lose Ihr bekommt, umso mehr Preise könnt Ihr gewinnen. Huzzah!", sourceObjectiveStatus = "unverified-source-field" }
quests[7907] = { id = 7907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestienkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt wo Ihr alle Karten des Bestienkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Bestienkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe habt Ihr es geschafft ein Set der Bestienkarten zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft das Bestienkartenset zu komplettieren. Das Ihr uns die Karten zurückgebt wird ein Band zwischen Euch und denen des Dunkelmonds schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten als Zeichen unserer Dankbarkeit zu schenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[7908] = { id = 7908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Arena", description = "Um der Meister der Arena zu werden, bedarf es bestimmt noch weiterer Taten! Vielleicht weiß der Pirat, der das Ereignis in Gurubashi veranstaltet, mehr.", sourceObjective = "Begebt Euch in die Arena des Schlingendorntals und sprecht mit Störtebrecher.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[7926] = { id = 7926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dunkelmond-Jahrmarkt", description = "Der Dunkelmond-Jahrmarkt kommt! Lasst Euch beim Besuch in Eurer Stadt nicht all die Wunder und Attraktionen entgehen!\n\nZögert nicht und Ihr werdet diesen Gutschein für kostenfreie Gewinnlose einlösen können! Bringt Euren Gutschein einfach zu Gelvas Rußgatter, der sich innerhalb des Jahrmarkts aufhält.\n\nMomentan hat der Jahrmarkt seine Zelte außerhalb von Donnerfels in Mulgore aufgeschlagen. Lasst Euch diese Gelegenheit nicht entgehen! Heute ist Euer Tag!", sourceObjective = "Bringt den Gutschein zu Gelvas Rußgatter, der sich innerhalb des Dunkelmond-Jahrmarkts aufhält.", progress = "Ja, kann ich Euch vielleicht behilflich sein? Habt Ihr einen Gutschein zum Einlösen?", completion = "Willkommen beim Dunkelmond-Jahrmarkt! Dieser Gutschein ist gültig für FÜNF, ja, FÜNF Gewinnlose!\n\nHabt Ihr Gewinnlose angesammelt, dann werdet Ihr mit mir sprechen wollen, um sie gegen wertvolle Preise einzutauschen. Je mehr Lose Ihr bekommt, umso mehr Preise könnt Ihr gewinnen. Huzzah!", sourceObjectiveStatus = "unverified-source-field" }
quests[7927] = { id = 7927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portalkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt wo Ihr alle Karten des Portalkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Portalkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Ah, Ihr habt das Portalkartenset nun vollständig beisammen! Glückwunsch!", completion = "Ihr habt es also geschafft das Portalkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7928] = { id = 7928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsfürstenkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt wo Ihr alle Karten des Kriegsfürstenkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Kriegsfürstenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Ah, Ihr habt das Kriegsfürstenkartenset nun vollständig beisammen! Glückwunsch!", completion = "Ihr habt es also geschafft das Kriegsfürstenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7929] = { id = 7929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt wo Ihr alle Karten des Elementarkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Elementarkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Ah, Ihr habt das Elementarkartenset nun vollständig beisammen! Glückwunsch!", completion = "Ihr habt es also geschafft das Elementarkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7930] = { id = 7930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "5 Lose - Dunkelmond-Blume", progress = "Kommt näher, kommt näher! Wenn ihr Lose vom Dunkelmond-Jahrmarkt habt, die ihr einlösen möchtet, dann sagt nur Bescheid! Ihr könnt Lose gegen zahlreiche, wundersame und fantastische Preise einlösen. Scheut euch nicht, probiert es aus!", completion = "Bitteschön, bitteschön! Ein passender Preis für einen König!  Meinen Glückwunsch!\n\nSolltet Ihr noch mehr Lose haben, die Ihr einlösen möchtet, dann lasst es mich bitte wissen!  Solange der Dunkelmond-Jahrmarkt hier ist, werde ich Eure Lose entgegennehmen." }
quests[7931] = { id = 7931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "5 Lose - Kleiner Dunkelmond-Preis", progress = "Kommt näher, kommt näher! Wenn ihr Lose vom Dunkelmond-Jahrmarkt habt, die ihr einlösen möchtet, dann sagt nur Bescheid! Ihr könnt Lose gegen zahlreiche, wundersame und fantastische Preise einlösen. Scheut euch nicht, probiert es aus!", completion = "Bitteschön, bitteschön! Ein passender Preis für einen König!  Meinen Glückwunsch!\n\nSolltet Ihr noch mehr Lose haben, die Ihr einlösen möchtet, dann lasst es mich bitte wissen!  Solange der Dunkelmond-Jahrmarkt hier ist, werde ich Eure Lose entgegennehmen." }
quests[7932] = { id = 7932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "12 Lose - Geringer Dunkelmond-Preis", progress = "Kommt näher, kommt näher! Wenn ihr Lose vom Dunkelmond-Jahrmarkt habt, die ihr einlösen möchtet, dann sagt nur Bescheid! Ihr könnt Lose gegen zahlreiche, wundersame und fantastische Preise einlösen. Scheut euch nicht, probiert es aus!", completion = "Bitteschön, bitteschön! Ein passender Preis für einen König!  Meinen Glückwunsch!\n\nSolltet Ihr noch mehr Lose haben, die Ihr einlösen möchtet, dann lasst es mich bitte wissen!  Solange der Dunkelmond-Jahrmarkt hier ist, werde ich Eure Lose entgegennehmen." }
quests[7933] = { id = 7933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "40 Lose - Großer Dunkelmond-Preis", progress = "Kommt näher, kommt näher! Wenn ihr Lose vom Dunkelmond-Jahrmarkt habt, die ihr einlösen möchtet, dann sagt nur Bescheid! Ihr könnt Lose gegen zahlreiche, wundersame und fantastische Preise einlösen. Scheut euch nicht, probiert es aus!", completion = "Bitteschön, bitteschön! Ein passender Preis für einen König!  Meinen Glückwunsch!\n\nSolltet Ihr noch mehr Lose haben, die Ihr einlösen möchtet, dann lasst es mich bitte wissen!  Solange der Dunkelmond-Jahrmarkt hier ist, werde ich Eure Lose entgegennehmen." }
quests[7934] = { id = 7934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "50 Lose - Dunkelmond-Lagerbehälter" }
quests[7935] = { id = 7935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "10 Lose - Hammel des letzten Monats", progress = "Kommt näher, kommt näher! Wenn Ihr Lose vom Dunkelmond-Jahrmarkt habt, die Ihr einlösen möchtet, dann sagt nur Bescheid! Ihr könnt Lose gegen zahlreiche wundersame und fantastische Preise einlösen. Scheut Euch nicht, probiert es aus!", completion = "Bitte schön, bitte schön! Ein passender Preis für einen König! Meinen Glückwunsch!\n\nSolltet Ihr noch mehr Lose haben, die Ihr einlösen möchtet, dann lasst es mich bitte wissen! Solange der Dunkelmond-Jahrmarkt hier ist, werde ich Eure Lose entgegennehmen." }
quests[7936] = { id = 7936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "50 Lose - Hammel des letzten Jahres" }
quests[7937] = { id = 7937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer Schicksal erwartet Euch...", description = "\"Euer Schicksal erwartet Euch im Osttal.\"\n\nDas Horoskop, das Sayge Euch überreicht hat, fühlt sich beim Berühren leicht warm an. Haltet Ihr es etwas fester in der Hand, so seht Ihr das Holzfällerlager des Osttals im Wald von Elwynn vor Euch. Beim Fokussieren auf dieses Bild, seht Ihr einen Heuhaufen neben einem Stall.", sourceObjective = "Reist zum Holzfällerlager des Osttals im Wald von Elwynn und sucht nach Eurem Schicksal.", progress = "Dieser Heuhaufen sieht aus wie der aus Eurer Vision.", completion = "Eine rasche Durchsuchung des Heuhaufens bringt eine Schließkassette ans Licht! Es scheint als hättet Ihr Euer Schicksal gefunden!", sourceObjectiveStatus = "unverified-source-field" }
quests[7938] = { id = 7938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer Schicksal erwartet Euch...", description = "\"Euer Schicksal erwartet Euch in den Todesminen.\"\n\nDas Horoskop, das Sayge Euch überreicht hat, fühlt sich beim Berühren leicht warm an. Haltet Ihr es etwas fester in der Hand, so seht Ihr die Todesminen in Westfalls Ruinen von Mondbruch. Beim Fokussieren auf dieses Bild, windet Ihr Euch durch verwinkelte Passagen bis Ihr ein schimmerndes Portal erreicht... eines, das in das Herz der Minen selbst führt. Beim Durchschreiten taucht eine seltsame Truhe aus dem Nichts auf.", sourceObjective = "Reist zu den Todesminen in Westfall und sucht nach Eurem Schicksal.", sourceObjectiveStatus = "unverified-source-field" }
quests[7939] = { id = 7939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr verdichtete Schleifsteine", progress = "{name}, ich danke Euch für all Eure Hilfe. Ich kann Euch wirklich nicht genug danken!\n\nIch brauche jetzt zwar nichts mehr wirklich... aber solltet Ihr mir mehr verdichtete Schleifsteine bringen, so habe ich auch noch einige Lose des Dunkelmond-Jahrmarkts für Euch.", completion = "Nochmals danke, {name}. Viel Spaß mit diesen Losen, und erzählt Euren Freunden vom Dunkelmond-Jahrmarkt!" }
quests[7940] = { id = 7940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "1200 Lose - Kugel des Dunkelmonds", progress = "Kommt näher, kommt näher! Wenn ihr Lose vom Dunkelmond-Jahrmarkt habt, die ihr einlösen möchtet, dann sagt nur Bescheid! Ihr könnt Lose gegen zahlreiche, wundersame und fantastische Preise einlösen. Scheut euch nicht, probiert es aus!", completion = "Bitteschön, bitteschön! Ein passender Preis für einen König!  Meinen Glückwunsch!\n\nSolltet Ihr noch mehr Lose haben, die Ihr einlösen möchtet, dann lasst es mich bitte wissen!  Solange der Dunkelmond-Jahrmarkt hier ist, werde ich Eure Lose entgegennehmen." }
quests[7941] = { id = 7941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Rüstungssets", progress = "{name}, ich muss mich für all Eure Hilfe bedanken. Ich verfüge jetzt über eine Menge an Vorräten, dank Eurer Bemühungen, aber wenn Ihr mir noch mehr Rüstungssets bringen möchtet, dann werde ich sie gerne gegen ein paar Lose des Dunkelmond-Jahrmarkts eintauschen.", completion = "Hier, {name}. Ein fairer Tausch. Viel Vergnügen." }
quests[7942] = { id = 7942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Thoriumapparate", progress = "{name}, Ihr wart so gut zu uns, indem Ihr uns ohne Unterlass Waren beschafft habt. Ich bin Euch dafür unendlich dankbar!\n\nAuch wenn wir einen nicht mehr so großen Bedarf an Thoriumapparaten wie zuvor haben, so könnt Ihr mir doch jederzeit weitere bringen. Ich tausche sie dann gegen Lose des Dunkelmond-Jahrmarkts ein.", completion = "Hier, {name}. Nehmt diese Lose des Dunkelmond-Jahrmarkts und vergnügt Euch damit. Gebt sie nicht alle auf einmal aus, wie man so schön sagt!" }
quests[7943] = { id = 7943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Fledermausaugen" }
quests[7944] = { id = 7944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer Schicksal erwartet Euch...", description = "\"Euer Schicksal erwartet Euch in den Höhlen des Wehklagens.\"\n\nDas Horoskop, das Sayge Euch überreicht hat, fühlt sich beim Berühren leicht warm an. Haltet Ihr es etwas fester in der Hand, so seht Ihr eine Höhle im Südwesten des Wegekreuzes im Brachland. Beim Fokussieren auf dieses Bild, windet Ihr Euch durch gewundene Passagen bis Ihr ein schimmerndes Portal erreicht... eines, das in das Herz der Höhlen selbst führt. Beim Durchschreiten taucht eine seltsame Truhe aus dem Nichts auf.", sourceObjective = "Reist zu den Höhlen des Wehklagens im Brachland und sucht nach Eurem Schicksal.", sourceObjectiveStatus = "unverified-source-field" }
quests[7945] = { id = 7945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer Schicksal erwartet Euch...", description = "\"Euer Schicksal erwartet Euch außerhalb des Bleichmähnenfelsens.\"\n\nDas Horoskop, das Sayge Euch überreicht hat, fühlt sich beim Berühren leicht warm an. Haltet Ihr es etwas fester in der Hand, so seht Ihr den Bleichmähnenfels von Mulgore. Beim Fokussieren auf dieses Bild seht Ihr einen Baumstumpf in der Nähe des Höhleneingangs.", sourceObjective = "Reist zum Bleichmähnenfels in Mulgore und sucht nach Eurem Schicksal.", progress = "Dieser Baumstumpf sieht aus wie der aus Eurer Vision.", completion = "Eine rasche Untersuchung des Baumstumpfs bringt eine Schließkassette ans Licht! Es scheint als hättet Ihr Euer Schicksal gefunden!", sourceObjectiveStatus = "unverified-source-field" }
quests[7946] = { id = 7946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jubjubs Nachwuchs", progress = "Ich bin so froh, dass Jubjub wieder da ist. Die Kleine liebt Dunkeleisenbier so sehr, dass sie, als mein Vorrat zuneige ging, weggerannt ist, um mehr davon zu suchen.\n\nJetzt, da Jubjub zurück ist, versuche ich, soviel Bier wie möglich zu kriegen! Ich möchte nicht, dass sie wieder wegläuft, wisst Ihr?\n\nHabt Ihr vielleicht etwas Dunkeleisenbier dabei? Wenn ja, gebe ich Euch eines von Jubjubs Froscheiern für einen Krug Dunkeleisenbier...", completion = "Vielen Dank, {name}. Hier ist Euer Ei! Es wird noch etwas dauern bevor es ausgebrütet werden kann, doch wenn es soweit ist habt Ihr ein großartiges Haustier!" }
quests[7961] = { id = 7961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waskily Wabbits!", sourceObjective = "Sammelt 10 unglückbringende Hasenpfoten.", sourceObjectiveStatus = "unverified-source-field" }
quests[7962] = { id = 7962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaninchenfelle", description = "Ich brauche einige LeCraft-Kaninchenfelle. Besorgt mir einige von den LeCrafty-Kaninchen.\n\nEine wichtige Aufgabe!", sourceObjective = "Bringt 3 LeCraft-Kaninchenfelle zu Jon LeCraft.", sourceObjectiveStatus = "unverified-source-field" }
quests[7981] = { id = 7981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "1200 Lose - Amulett des Dunkelmonds" }
