quests[8041] = { id = 8041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärke des Bergs Mugamba", sourceObjective = "Seid gegrüßt, {class}. Ich bin Jin'rokh der Zerstörer, Troll von Mugamba. Wir vom Stamm der Zandalar erkennen Eure Leistungen an. Wir begrüßen Eure Hartnäckigkeit und Willenskraft.\n\nTragt diesen Talisman um Euren Hals, {class}. Lasst die Stärke des Bergs Mugamba durch Euch hindurch fließen. Fühlt die Macht, wenn Ihr unsere Feinde niederstreckt!", sourceObjectiveStatus = "unverified-source-field" }
quests[8042] = { id = 8042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärke des Bergs Mugamba", progress = "Gut zu sehen, dass Ihr wohlauf seid, {name}. Die glorreichen Schlachten, in denen Ihr Euch geschlagen habt, wirken sich auf das Leben des gesamten Planeten aus. Hakkar darf die Grenzen von Zul'Gurub niemals überschreiten, da die Welt seinem immensen Hunger mit Sicherheit nicht standhalten könnte.\n\nGebt mir Euren Talisman und ich werde seine Stärke noch mächtiger machen. Setzt die Stärke von Mugamba zum Bestrafen unserer Feinde ein!", completion = "Unsere Wege werden sich erneut kreuzen, {class}." }
quests[8043] = { id = 8043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärke des Bergs Mugamba", progress = "Meister {name}, Ihr kehrt zurück! Molthor hat bereits Kunde von Euren Taten zum König geschickt. Euer Name ist sogar in den südlichen Meeren bekannt. Vielleicht werdet Ihr eines Tages ein legendärer {class} sein... eine Legende für die Ewigkeit.\n\nGebt mir Euren Talisman, damit ich seine Macht noch einmal verstärken kann.", completion = "Nutzt Eure wiedererlangte Stärke, um die Gurubashi zu vernichten!" }
quests[8044] = { id = 8044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wut Mugambas", progress = "König Rastakhan sendet Euch seine Grüße, Meister {name}. Eine solche Ehre wurde noch nie jemanden zuteil, der nicht zum Stamm der Zandalar gehört.\n\n\n\nGebt mir Euren Talisman, damit ich ihn noch einmal verstärken kann. Ihr sollt wissen, dass die Wut Mugambas jetzt untrennbar mit Eurer Seele verbunden ist.", completion = "Zul'jin würde Euch beneiden, {class}. Zieht hinfort und siegt!" }
quests[8045] = { id = 8045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Emblem des Ungläubigen", sourceObjective = "Wisset, Ungläubiger: eine Katastrophe hat uns vereint. Eure heidnischen Wege werden von den Zandalarianern weder verstanden, noch geschätzt, aber wir sind ein faires Volk. Tragt dieses Emblem um Euren Hals. Es soll unseren Feinden als Warnung und den Zandalarianern als Zeichen der Freundschaft dienen.\n\nDient auch weiterhin unserem Stamm und ich werde die Macht des Emblems verstärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[8046] = { id = 8046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Emblem des Ungläubigen", progress = "Ich war vielleicht etwas zu vorschnell mit meinem Urteil, {class}. Es scheint, als wäre Euer blindes Vertrauen in das Licht nach all dem doch noch von Wert.\n\nGebt mir Euer Emblem, damit ich seine Macht verstärken kann.", completion = "Tut, was Ihr tun müsst, um unsere Feinde zu vernichten, {class}. Selbst wenn Ihr dafür das Licht kanalisieren müsst." }
quests[8047] = { id = 8047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Emblem des Ungläubigen", progress = "Ich muss gestehen, dass ich nicht daran geglaubt habe, dass Ihr die Entschlossenheit besitzt, um dieser Sache Herr zu werden, {class}. Für Zandalar seid Ihr jetzt ein Verbündeter von unschätzbarem Wert. Gut gemacht, in der Tat.\n\nGebt mir Euer Emblem und und ich werde seine Macht noch einmal verstärken.", completion = "Unsere Überzeugungen unterscheiden sich zwar, aber unsere Gründe sind gerechtfertigt. Bezwingt unsere Feinde, edler {class}." }
quests[8048] = { id = 8048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Emblem des Helden", progress = "Der König nimmt Eure Existenz zur Kenntnis, {class}. Ihr seid der erste Eurer Art, der von Rastakhan als wahrer Verbündeter der Zandalarianer akzeptiert wird.\n\nIhr werdet für Eure Bemühungen reichlich belohnt werden. Zeigt Euer Emblem vor und ich werde auch noch dessen letzte Verstärkung vornehmen.", completion = "Wachsamkeit, Ehre, Treue, Mut... Ihr verkörpert alle diese Eigenschaften und so soll es auch Euer Emblem tun." }
quests[8049] = { id = 8049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge von Zuldazar", sourceObjective = "Nehmt diesen Talisman als Zeichen unserer Wertschätzung an, {class}.\n\nDas Auge von Zuldazar wird umso mächtiger, je stärker Euer Bund mit den Trollen von Zandalar wird. Kommt von Zeit zu Zeit zu mir zurück und ich werde das Juwel mit Macht erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8050] = { id = 8050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge von Zuldazar", progress = "Willkommen {class}. Das Auge von Zuldazar pulsiert voller Energie. Ihr seid für die nächste Stufe bereit. Überreicht mir den Talisman, damit ich ihn mit Macht erfüllen kann.", completion = "Führt Euren Kampf gegen den Seelenschinder und seine Diener fort, {name}. Er darf die Grenzen Zul'Gurubs niemals überschreiten." }
quests[8051] = { id = 8051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge von Zuldazar", progress = "Überall verbreiten sich Geschichten von Euren Schlachtzügen gegen die Gurubashi, {class}. Sogar im Königshaus wird jetzt von Euren Heldentaten gesprochen. Man sagt, dass König Rastakhan sogar Euren Namen erwähnt hat.\n\nNun ist es an der Zeit das Auge zu erfüllen. Reicht mir den Talisman und ich werde Euch diesen Dienst erweisen.", completion = "Geht entschlossen bei Euren Bestrebungen vor, {name}. Der Seelenschinder wird versuchen Euch Euren Lebenswillen zu entziehen." }
quests[8052] = { id = 8052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das allsehende Auge von Zuldazar", progress = "Wenn wir nur zehntausend mehr wie Euch hätten, {name}. Die Armeen Hakkars würden in kürzester Zeit niedergeschmettert werden.\n\n\n\nAch, das Auge ist nun für die Erfüllung seines wahren Potentials bereit. Gebt es mir.", completion = "Tötet sie alle und überlasst Hakkar das Aufräumen..." }
quests[8053] = { id = 8053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Die Armschützer des Freidenkers", description = "Ihr seid ungläubig. Ungläubige haben einen Platz in unserem Stamm. Ungläubige sind Freidenker der Zandalari. Freidenker fürchten sich nicht vor Unterdrückung und sterben für das, woran sie glauben. Wir wissen, dass Ihr für das, woran Ihr glaubt, sterben würdet. Dies verdient unsere Anerkennung. Ihr dürft Euch uns auch weiterhin als würdig erweisen.\n\nWir brauchen die Symbole der Macht. Geht nach Zul'Gurub. Tötet die Diener Hakkars. Sobald Ihr habt, wonach ich verlange, kommt zu mir zurück. Strebt nach der ersten Kampfausrüstung eines Zandalarifreidenkers.\n\nUnd nun geht.", sourceObjective = "Bringt urzeitliche Hakkaribindungen zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Ihr seid zurück? Habt Ihr das Symbol der Macht? Wollt Ihr meine Zeit verschwenden?\n\nIch hoffe doch nicht.", completion = "Ihr ehrt uns sehr. Eure Hände sind mit dem Blut der Diener Hakkars befleckt. Ihr seid ein Freund unseres Stammes.\n\nTragt diese Armschienen. Es sind Armschützer des Freidenkers. Das war es, was ich mit wahrer Macht meinte.", sourceObjectiveStatus = "unverified-source-field" }
quests[8054] = { id = 8054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Der Gürtel des Freidenkers", description = "Eure Überzeugungen sind uns fremd, <Ungläubiger/Ungläubige>. Die Uralten von Zandalar wurden einst als Heiden gebrandmarkt. Dies war in der Zeit als das Imperium der Gurubashi noch mächtig war. Ungläubige wagten es, den Priester Hakkars herauszufordern. Sie wurden daraufhin gejagt und wie Ungeziefer vernichtet. Diese Ungläubigen wankten niemals in ihrem Kampf gegen den Blutgott. Wir wissen den Preis, den sie dafür bezahlen mussten, zu schätzen. Sie sind die Freidenker.\n\nMacht den Dienern Hakkars in Zul'Gurub den Garaus. Bringt mir das Symbol der Macht, nach denen ich verlange. Erfolgreiche Taten sollen großzügig belohnt werden.\n\nUnd nun geht.", sourceObjective = "Bringt einen urzeitlichen Hakkarischal zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Eure Anwesenheit kündet von Erfolg? Habt Ihr das Symbol? Badet Ihr bereits im Blut Eurer Feinde?", completion = "Das Wohlwollen in unserem Stamm ist Euch sicher. Zahlreiche Tote in Zul'Gurub gehen auf Euer Konto. Viele Feinde wurden von Euch gerichtet.\n\nDies ist der Gürtel des Freidenkers. Er steht für Ehre und ist mächtiges Mojo. Jetzt ist er Euer Eigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8055] = { id = 8055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Die Brustplatte des Freidenkers", description = "Im Stamm verleiht die Kampfausrüstung Macht. Die Freidenker sind auf diese Weise geehrt. Sie sind Zeloten. Sie tränken ihre Brustplatten mit mächtigem Mojo. Wenn ihr Glaube im Angesicht des Feindes zu wanken beginnt, so werden ihre Brustplatten dennoch standhalten.\n\nIhr müsst von uns respektiert werden, um solch eine Brustplatte zu besitzen. Geht nach Zul'Gurub. Ihr müsst das von mir benötigte Symbol der Macht beschaffen. Entwendet es den Narren auf schmerzlichste Art und Weise. Bringt es zu mir. Beweist Euch ein für alle Mal als Freidenker würdig.", sourceObjective = "Bringt einen urzeitlichen Hakkariwappenrock zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Habt Ihr das Symbol? Es beinhaltet Mojo. Wir müssen es haben. Ihr werdet uns helfen.", completion = "Ihr habt vollbracht, was nur wenige hätten tun können. Ihr habt die Diener Hakkars in die Knie gezwungen. Ihr habt ihnen gezeigt, zu was ein Freidenker fähig ist. Ihr habt uns bewiesen, dass auch ein Ungläubiger in diesem Stamm anerkannt werden kann. Ihr seid mehr als mächtig. Ihr SEID die Macht.\n\nNehmt die Brustplatte, Freidenker. Zerstört diejenigen, die sich Euch in den Weg stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8056] = { id = 8056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Die Armschienen des Weissagers", description = "Die Weissager unseres Stammes werden für ihre Gaben der göttlichen Sicht respektiert, ja wirklich. Sie sind nicht etwa eine Art Hexendoktor, nein, sie verbringen ihre Zeit mit dem Beschwören von Knochen oder dem Lesen von Blättern der Einsicht, und nicht mit dem Verhexen anderer. Als Schamane wisst Ihr bereits etwas über die Macht der Weissagung; wir Zandalari würdigen die Einsicht, die unserem Stamm gegeben wird.\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und erweist Euch als uns würdig. Helft Ihr uns, werde ich Euch Armschienen geben, die unsere Weissager mehr als alles andere verehren!", sourceObjective = "Bringt urzeitliche Hakkariarmsplinte zu Maywiki von Zuldazar. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nMaywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Habt Ihr das von mir benötigte Symbol der Macht von Zul'Gurub? Diese Armschienen sind die Bemühungen Eurerseits wahrlich wert!", completion = "Es scheint als würdet Ihr etwas von der zandalarianischen Weissagung in Euch tragen. Wir wissen von Euren Taten in Zul'Gurub, die Ihr für uns vollbracht habt. Dieses Symbol der Macht wird einen langen Weg gehen, um dem Stamm der Zandalar zu helfen - einem Stamm, wenn ich hinzufügen darf, mit dem Ihr Euch als befreundet betrachten dürft. Nehmt die Armschienen, {name}; Ihr habt sie Euch verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[8057] = { id = 8057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Die Haruspexarmschienen", description = "Ein Haruspex ist ein wichtiges Mitglied in unserem Stamm, ihr tut gut daran auf ihr Omen zu hören. Mittels spiritueller Vereinigung mit den Tieren und deren Opferung, falls nötig, schenken sie uns göttliche Leitung. In der Vergangenheit verschaffte uns die Einsicht und Weisheit der Haruspex einen Vorteil in den Kämpfen gegen die zersplitterten Stämme der Gurubashi.\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und erweist Euch als uns würdig. Solltet Ihr erfolgreich sein, so werde ich Euch mit Armschienen belohnen, die selbst ein Haruspex der Zandalari begehrt.", sourceObjective = "Bringt eine urzeitliche Hakkaristütze zu Maywiki von Zuldazar. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nMaywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Habt Ihr das erforderliche Symbol der Macht von Zul'Gurub beschaffen können? Diese Armschienen sind die Bemühungen mehr als wert, {name}. Glaubt mir!", completion = "Ah, ich kann die Macht, die von den Symbolen ausgeht, spüren, {name}. Ihr habt Euch in den Augen des Stammes als jemanden, den man einen \"Freund\" nennt, bewiesen. Geschäft ist Geschäft, {name}... spürt die Macht der Haruspexarmschienen!", sourceObjectiveStatus = "unverified-source-field" }
quests[8058] = { id = 8058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Die Armschützer des Vollstreckers", description = "Rache ist Macht. Der Vollstrecker der Zandalari ist solch eine Macht. Unser Stamm hat viele Feinde. Der Vollstrecker fordert Vergeltung von ihnen ein. Kein Verbrechen gegen uns bleibt unbestraft und der Vollstrecker sorgt für diese Bestrafung. Unsere Feinde fürchten sich vor unserer Rache. Das sollen sie auch, und sie werden es auch für immer tun.\n\nWerdet einer unserer Vollstrecker. Sucht nach den Symbolen der Macht in Zul'Gurub. Tötet die Diener Hakkars und sorgt im Namen unseres Stammes für Vergeltung. Ihr werdet belohnt werden.", sourceObjective = "Bringt urzeitliche Hakkariarmsplinte zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Habt Ihr das Symbol der Macht bekommen? Wurde im Namen der Zandalar Vergeltung geübt?", completion = "Ihr habt heute ausreichend Rache walten lassen. Ihr habt das Antlitz des Vollstreckers angenommen und die Diener des Blutgottes in die Knie gezwungen.\n\nNehmt dies. Eure Rache wird damit für die Zukunft geschürt. Ihr seid nun ein Freund der Zandalar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8059] = { id = 8059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Die Handlappen des Besessenen", description = "Hexenmeister begeben sich bei ihrem Umgang mit Dämonen auf ein gefährliches Terrain, unsere Besessenen gehen jedoch noch einen Schritt weiter. Mithilfe eines uralten, arkanen Rituals erlauben sie es einem Dämon, in ihre Gestalt zu schlüpfen. Anstelle von ihm besessen zu werden, versklaven sie den Dämon von innen heraus und absorbieren die Macht des Ungetüms für ihre eigenen Zwecke. Es ist eine Fähigkeit, die nur wenige zu meistern verstehen.\n\nDamit Ihr von der Macht der Besessenen lernen könnt, müsst Ihr mir ein Symbol der Macht von Zul'Gurub beschaffen. Geht und bringt mir, wonach ich verlange.", sourceObjective = "Bringt eine urzeitliche Hakkaristütze zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Habt Ihr das Symbol der Macht? Indem Ihr die teuflischen Diener Hakkars vernichtet, beweist Ihr Euch nicht nur uns, sondern Ihr zeigt auch Euren Willen, die Wege der Besessenen erlernen zu wollen.", completion = "Gut gemacht... keine Frage, dass die Rückgabe des Symbols der Macht von ihnen mit qualvollen Schmerzen bezahlt werden musste. Nehmt dies - die Handlappen des Besessenen. Hergestellt aus mächtigem Mojo, das bei der Beschwörung der Beute von Besessenen verwendet wurde. Sie sind ein mächtiges Instrument bei dem Erwerb der Macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[8060] = { id = 8060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Die Handlappen des Illusionisten", description = "Magier sind in unserem Stamm als Illusionisten bekannt. Sie setzen bei ihren Beschwörungen mächtiges Mojo ein, bringen die Feinde des Stamms oft durcheinander und machen sie konfus!\n\n<Al'tabim lacht gehässig.>\n\nEs ist schon ein ziemliches Spektakel, wenn man einem mächtigen Illusionisten bei der Arbeit zusieht und beobachtet wie er unsere Feinde mithilfe ihres eigenen Wahnsinns in die Knie zwingt!\n\nWenn Ihr mehr über den Weg unserer Illusionisten lernen möchtet, dann geht nach Zul'Gurub und bringt ein bestimmtes Symbol der Macht zu mir zurück. Ich werde Euch dafür mit Handlappen belohnen, die unsere Illusionisten zum Weben ihrer Zauber verwenden.", sourceObjective = "Bringt urzeitliche Hakkaribindungen zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "{name} - schon wieder zurück? Konntet Ihr das Symbol der Macht, welches ich benötige, beschaffen?", completion = "Beeindruckend... konntet Ihr das Mojo durch diesen Gegenstand fließen spüren? Die Symbole der Macht wurden in den Zeiten, als das Imperium der Gurubashi noch vorherrschte, als eine Art Währung verwendet. Jetzt werden wir Zandalarianer das in ihnen schlummernde latente Mojo nutzen, um die zweite Auferstehung des Blutgottes Hakkar niederzukämpfen!\n\nIhr habt Euch heute tapfer geschlagen - betrachtet Euch als Freund der Zandalarianer. Hier, nehmt die Handlappen des Illusionisten wie versprochen als Belohnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[8061] = { id = 8061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Die Handlappen des Glaubenshüters", description = "Wir Zandalari investieren Macht in diejenigen, die mit der Gewalt des Göttlichen sprechen. Unsere Priester sind mehr als nur Heiler; sie sind auch unsere Hüter des Glaubens. Das Böse kommt von äußeren Bedrohungen, wie zum Beispiel Hakkar, wie auch von innerhalb des Stammes. Unsere Glaubenshüter agieren wie die Richter unter uns, sie schützen uns vor dem gleichen Übel, das bereits die Gurubashi sich selbst hat zerstören lassen.\n\nGeht nach Zul'Gurub und bringt die Symbole der Macht von den Gurubashi zurück. Lernt, was es heißt, ein Glaubenshüter zu sein, und schützt uns vor dem Bösen.", sourceObjective = "Bringt eine urzeitliche Hakkaristütze zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Zurück von Zul'Gurub, ja? Wart Ihr bei der Wiederbeschaffung des Symbols der Macht von den Dienern Hakkars erfolgreich?", completion = "Hervorragend, {name}! Diese Aufgabe war nicht gerade eine Kleinigkeit. Es besteht kein Zweifel daran, dass Ihr heute wie einer unserer Glaubenshüter gehandelt habt und uns somit vor der Bedrohung Hakkars beschützt habt. Diese Handlappen sind für einen Freund des Stammes, so wie Ihr einer seid, nur angemessen!", sourceObjectiveStatus = "unverified-source-field" }
quests[8062] = { id = 8062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Die Armschienen des Raubtiers", description = "In den dunklen Zeiten nach dem Fall des Imperiums der Gurubashi setzten die Jäger der Zandalari ihre Tapferkeit ein, um den Lebensunterhalt für den Stamm zu sichern. Man vergleicht sich gerne mit den Jägern unseres Stammes: Das Streben nach der Jagd bedeutet das Einswerden mit der Essenz des Jägers, ja. Eure Jagd in Zul'Gurub wird uns zeigen, in welchem Verhältnis Ihr zu unseren besten Jägern steht.\n\nBringt mir ein Muster der Symbole der Macht aus Zul'Gurub. Ihr werdet damit Eure ersten Schritte tun, die es braucht, um vorletzter Jäger zu werden.", sourceObjective = "Bringt das folgende Symbol der Macht aus Zul'Gurub zu Falthir dem Blinden: Urzeitliche Hakkaribindungen. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Jagt in Zul'Gurub nach denjenigen, die im Besitz eines Symbols der Macht sein könnten, {name}. Sie sind Eure Beute; sie besitzen das, nach dem wir beide verlangen.", completion = "Ja... ich brauche kein Augenlicht, um die Anwesenheit eines Symbols der Macht zu spüren. Euer Erfolg in Zul'Gurub hat viele in unserem Stamm beeindruckt. Wir betrachten Euch nicht nur als einen Freund der Zandalar, sondern auch als würdig genug die Raubtierarmschienen zu besitzen, einen mächtigen Gegenstand und ein Symbol dessen, was es bedeutet ein {class} zu sein. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8063] = { id = 8063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Die Armschienen des Wildfangs", description = "Die Wildfänge von Zandalar ähneln den Schurken, vertraut sind sie vor allem aber mit dem Wahnsinn... dem Chaos... der Unberechenbarkeit des Lebens. Als unvergesslicher Anblick des Terrors auf dem Schlachtfeld, säten sie in den wilden Zeiten nach Aufsplittung der Stämme Verwirrung und Chaos unter unseren Feinden. Ohne sie, würde es uns heute nicht geben.\n\nBringt mir das gewünschte Symbol der Macht von Zul'Gurub und ich werde Euch mit den so begehrten Armschienen des Wildfangs belohnen. Gebt Euch dem Wahnsinn hin!", sourceObjective = "Bringt urzeitliche Hakkariarmsplinte zu Falthir dem Blinden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Sucht nach dem Wahnsinn aus Zul'Gurub und überschattet ihn mit Eurem eigenen, {name}! Diese Tat bedeutet Erfolg und Erfolg bedeutet Belohnung! Überlasst dem Blutgott nicht wieder die totale Herrschaft!", completion = "Sehr schön, {name}... mit Euren Leistungen in Zul'Gurub habt Ihr Euch das Recht verdient, den Stamm der Zandalar Euren Freund nennen zu dürfen. Ich werde mich um die Symbole kümmern; nehmt diese Belohnung bitte als Dank für Eure Bemühungen an!", sourceObjectiveStatus = "unverified-source-field" }
quests[8064] = { id = 8064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Der Haruspexgürtel", description = "Die Zandalari kennen die Wege der Druiden nicht; die Natur soll nach unseren Bedürfnissen geformt werden und nicht umgekehrt. Dennoch gehören die Haruspex zu denen, die am meisten mit der Natur im Einklang leben, und das mit Recht. Den Geist eines Wildtiers zu opfern, bedeutet zu wissen, wie es ist einer von ihnen zu sein. Das ist die wahre Macht der Natur.\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und erweist Euch als uns würdig. Solltet Ihr erfolgreich sein, so werde ich Euch mit einem mächtigen Gegenstand belohnen: einem Gürtel, wie ihn viele Haruspex der Zandalari verwenden.\n\nStarkes Mojo, ja!", sourceObjective = "Bringt eine urzeitliche Hakkarischärpe zu Maywiki von Zuldazar. Maywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal. Die Einstellung des Stammes der Zandalari muss Euch gegenüber außerdem wohlwollend sein.", progress = "Habt Ihr das erforderliche Symbol der Macht von Zul'Gurub beschaffen können? Wenn ja, so wird der Haruspexgürtel Euer Eigen sein.", completion = "Ich danke Euch - die latente Macht in diesem Gegenstand ist der eigentliche Schatz in ihm selbst, darauf könnt Ihr Gift nehmen. Ihr habt nicht nur das erforderliche Symbol der Macht erfolgreich beschafft, ihr habt Euch auch bei unserem Stamm als ehrbar erwiesen. Hier, nehmt wie versprochen Eure Belohnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[8065] = { id = 8065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Die Haruspextunika", description = "Das ultimative Symbol der Macht eines Haruspex ist die Kleidung, die er trägt, {name}. Die Tunika symbolisiert die Verbindung zwischen ihnen selbst und der göttlichen Weisheit, nach der sie streben. Oft werden in die Tunika Teile der geopferten Tiere eingewoben, die sie an die Verbundenheit mit deren Talenten erinnern.\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und erweist Euch als uns würdig. Solltet Ihr erfolgreich sein, so wird Euch eine wie von mir beschriebene Tunika gehören.", sourceObjective = "Bringt einen urzeitlichen Hakkariwappenrock zu Maywiki von Zuldazar. Maywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal. Die Einstellung des Stammes der Zandalari muss Euch gegenüber außerdem respektvoll sein.", progress = "Habt Ihr das erforderliche Symbol der Macht von Zul'Gurub beschaffen können? Die Haruspextunika ist jede Mühe, die Ihr dafür erbringen müsst, wert.", completion = "Beeindruckend... Ihr habt das erforderliche Symbol der Macht erfolgreich beschafft, {name}. Eure vollbrachten Taten in Zul'Gurub im Namen der Zandalar sind sagenhaft; von nun an werdet Ihr in unserem Stamm angesehen werden. Hier ist Eure Tunika, mächtiger {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[8066] = { id = 8066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Der Gürtel des Raubtiers", description = "Ein Raubtier weiß, wie es sich an seine Beute heranschleicht, ein erfolgreiches Raubtier weiß aber auch, wie es seine Beute schlägt, sobald es zu ihr aufgeschlossen hat. Ihr müsst beides beherrschen, wenn Ihr in Zul'Gurub erfolgreich sein wollt... und wenn Ihr Euch mit den Jägern der Zandalari vergleichen wollt.\n\nBringt mir ein ausgesuchtes Teil der Symbole der Macht aus Zul'Gurub. Meine Belohnung wird die Macht sein, die diese Schmuckstücke enthalten, Eure wird dagegen der Gürtel des Zandalariraubtiers sein, ein Gegenstand, der den Tausch sehr wohl wert ist, glaubt mir.", sourceObjective = "Bringt das folgende Symbol der Macht aus Zul'Gurub zu Falthir dem Blinden: Einen urzeitlichen Hakkarischal. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Vernichtet die verrückten Diener Hakkars in Zul'Gurub - sie sind es, die im Besitz der Symbole der Macht sind, {name}. Beweist ihnen und dem Stamm Eure Überlegenheit als hoffnungsvoller {class}.", completion = "Ich habe Euer Kommen bereits gespürt, {name}, wenn auch beschwerlich. Was Euch verraten hat, war das Symbol der Macht, welches Ihr bei Euch tragt. Ich muss es nicht einmal sehen, ich kann seine Macht spüren; das in ihm ruhende Mojo - rohe Magie, könnte man sagen - schürt auch weiterhin unser Streben nach Vereitelung der teuflischen Pläne des Blugottes Hakkar an.\n\nMan kann Euch weiterempfehlen, und für Euren Erfolg belohnen. Im Stamm sieht man Euch mit Wohlwollen entgegen, ebenso verdient Ihr es, den Raubtiergürtel zu tragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8067] = { id = 8067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Der Mantel des Raubtiers", description = "Wir Zandalari schätzen unsere Kleidung als eine Art Symbol für vollbrachte Taten. Man muss nicht sehen können, was jemand trägt, um zu spüren, was davon ausgeht. Macht geht über die Sicht hinaus. Die Bekleidung von Zandalarijägern ist von dieser Art, und der wohl am meisten verehrte Teil davon ist der Mantel, den sie tragen. Er hilft ihnen ihr Erscheinungsbild zu verschleiern... und ihre Gegenwart dann bekannt zu geben, wenn sie es möchten.\n\nDie Symbole der Macht warten in Zul'Gurub darauf, von Euch zurückerobert zu werden. Bringt mir, wonach ich verlange, und der Mantel des Zandalariraubtiers soll Euer Eigen sein.", sourceObjective = "Bringt das folgende Symbol der Macht aus Zul'Gurub zu Falthir dem Blinden: Eine urzeitliche Aegis der Hakkari. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "War Euer Anschlag auf Zul'Gurub erfolgreich, {name}? Nur wenn Ihr mir gebracht habt, wonach ich verlange und Ihr Euch dem Stamm ganz und gar würdig erwiesen habt, werdet Ihr den Mantel erhalten, der wie kein anderer der Zandalarianer ist.", completion = "Erfolg... Ihr werdet vom Stamm respektiert werden, {name}. Die Beschaffung des Symbols der Macht, welches für den Mantel von Nöten ist, war eine waghalsige Leistung, die Ihr auf tödlichste Art und Weise unserer {class} gemeistert habt. Ihr habt Euch Euren Platz unter ihresgleichen verdient und sicherlich auch das Recht, ihren Mantel tragen zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8068] = { id = 8068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Der Mantel des Illusionisten", description = "Magie ist eine rohe, uralte Kraft, die von denen beherrscht werden muss, die stark genug dafür sind. Mojo ist unser verlängerter Arm dieser Macht; eine der mächtigsten Manipulationen davon ist die Form der Illusion. Wie kann man sich ernsthaft erhoffen einen Feind zu schlagen, der nicht einmal wirklich da ist? Wir Zandalari wissen von dieser Macht und daher wird den Illusionisten eine besondere Stellung in unserem Stamm zuteil.\n\nBeschafft das notwendige Symbol der Macht von Zul'Gurub... dafür werdet Ihr mit dem Wohlwollen unseres Stammes und einem mächtigen Mantel, wie er von unseren besten Illusionisten verwendet wird, belohnt werden!", sourceObjective = "Bringt einen urzeitlichen Hakkarischal zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Wie war Euer Ausflug nach Zul'Gurub? Habt Ihr Eure Feinde mit der Macht der Illusion in den Wahnsinn getrieben? Illusion ja oder nein, ihr Tod - und die von ihnen wiedererlangten Symbole der Macht - werden die Auferstehung Hakkars vereiteln.", completion = "Erfolg! Man wird Euch von jetzt an in unserem Stamm mit Wohlwollen entgegenkommen! Zul'Gurub hat heute mit Sicherheit die Macht der Zandalarianer zu spüren bekommen, dank Euch, {name}.\n\nIhr habt den Segen unseres Stammes, bitte nehmt den zandalarianischen Mantel des Illusionisten. Möge er Euch gut dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8069] = { id = 8069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Die Roben des Illusionisten", description = "Im Stamm wird Stellung und Macht durch das ausgezeichnet, was man trägt. Unsere Kleidung wird aus den feinsten Materialien hergestellt und mit Mojo verwoben, mit dessen Hilfe wir uns Macht verleihen. Illusionisten sind keine Ausnahme; man sagt, dass ihre Roben mittels ihres Aussehens die Essenz der Illusion verkörpern. Legenden besagen, dass ihre uralten Roben niemals gleich aussahen.\n\nIch werde Euch die Robe eines Illusionisten geben, {name}... aber zuerst müsst Ihr Euch in unserem Stamm Respekt verdienen! Bringt mir ein Symbol der Macht von Zul'Gurub!", sourceObjective = "Bringt einen urzeitlichen Hakkarikosak Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Seid Ihr mit dem Symbol der Macht, das wir benötigen, zurückgekehrt? Ich weiß, dass es nicht einfach sein wird... aber ich habe schon seit langem prophezeit, dass ein Außenseiter kommen würde und uns bei unserem Kampf gegen Hakkar zur Seite stehen würde. Ich denke Ihr solltet es sein!", completion = "Wenigsten jemand, der würdig ist die Robe des Illusionisten zu tragen! Euer Erfolg in Zul'Gurub hat Euch für alle Zeit Respekt von unserem Stamm eingebracht. Tragt sie mit Stolz, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[8070] = { id = 8070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Die Bindungen des Glaubenshüters", description = "Kurze Zeit nach dem Fall der Gurubashi wurden wir Zandalari fast endgültig vom Bösen innerhalb unseres Stammes besiegt. Es war zu dieser Zeit, dass die sich Glaubenshüter unter uns erhoben, um den Stamm zu schützen und diejenigen zu verbannen, die unsereins zu zerstören trachteten. Sie erhalten nicht nur den Einklang zwischen uns und den Geistern, sie erhalten auch unsere Leiber.\n\nReist weit nach Zul'Gurub und werdet selbst Zeuge von der Verdorbenheit Hakkars und der Gurubashis. Entringt ihnen die Symbole der Macht, nach denen wir suchen, und Euer Erfolg soll belohnt werden!", sourceObjective = "Bringt eine urzeitliche Hakkarischärpe zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Das Symbol der Macht... Habt Ihr es? Nur wenn wir es haben, werden wir in der Lage sein, die in ihm schlummernde, latente Macht zu nutzen. Es wird nur gut sein den Spieß für die Diener des Blutgottes einmal umzudrehen...", completion = "Erfolg! Es wird noch eine Zeit brauchen, um Macht gegen die Auferstehung Hakkars aufzubauen. Mit Eurer Hilfe konnten wir einen ausschlaggebenden Schritt vorangehen und somit sicherstellen, dass der Blutgott uns nicht alle zerstören wird.\n\nIhr habt Euch heute das Wohlwollen unseres Stammes verdient, {name}. Nehmt dies hier, die Bindungen des Glaubenshüters, als Zeichen unseres Dankes.", sourceObjectiveStatus = "unverified-source-field" }
quests[8071] = { id = 8071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Der Mantel des Glaubenshüters", description = "Alle Glaubenshüter der Zandalari tragen einen bestimmten Mantel, der sie als Beschützer des Stammes auszeichnet. Diese Mäntel werden aus mächtigem Mojo gewoben, das beim Beurteilen derjenigen behilflich ist, die eine Bedrohung für unseren Stamm darstellen. Auch Ihr müsst als Priester Zeit aufwenden, um zu beurteilen, wer würdig ist und wer nicht; ein solcher Mantel wäre zweifellos ein Segen für Euch.\n\nWenn Ihr Hakkars Diener in Zul'Gurub besiegt und mir das benötigte Symbol der Macht besorgt, werde ich Euch im Austausch dafür einen Mantel geben, der unter unseren Glaubenshütern als hoch und heilig gilt.", sourceObjective = "Bringt eine urzeitliche Aegis der Hakkari zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Habt Ihr das Symbol der Macht von Zul'Gurub?", completion = "Gut gemacht, {name} - die Diener Hakkars haben heute dank Euch zweifellos die Vergeltung der Zandalarianer zu spüren bekommen. Eure Taten haben Euch auf Dauer zu Respekt in unserem Stamm verholfen. Ihr habt unseren Segen, betrachtet den Mantel des Glaubenshüters bitte als den Eurigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[8072] = { id = 8072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Der Mantel des Wildfangs", description = "Khar'vaxal der Irrsinnige war einer der legendären Wildfänge der Zandalari. Legenden zufolge benutze er seinen Mantel, der speziell aus \"Stoff des Wahnsinns\" gewoben wurde, als er den Feinden des Stammes zum ersten Mal gegenübertrat. Seine Gestalt wurde nicht nur von dem Mantel, sondern auch dank der blendenden Geschwindigkeit seiner Zwillingsdolche verschleiert. Heute verehren die Wildfänge ihren Mantel als Zeichen der Stammeszugehörigkeit und der Stellung, die ihnen zusteht.\n\nBringt mir das gewünschte Symbol der Macht und ein derartiger Mantel wird Euch gehören und Eure Feinde in Wahnsinn hüllen.", sourceObjective = "Bringt einen urzeitlichen Hakkarigurt zu Falthir dem Blinden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Ihr seid zurück - habt Ihr das von mir benötigte Symbol der Macht?\n\nDie Legende von Khar'vaxal dem Irrsinnigen dient uns heute als Erinnerung dafür, dass kein Feind unbesiegbar ist, egal wie groß dessen Bedrohung auch sein mag. Chaos zwingt alles und jeden in die Knie, so viel ist sicher... vielleicht sogar einige der unchaotischen Elemente des Chaos selbst.", completion = "Heute ist der Sieg auf unserer Seite, dank des Wahnsinns, den Ihr über unsere gemeinsamen Feinde habt hereinbrechen lassen! Das Wohlwollen der Zandalar ist Euch sicher und wir könnten unserem Dank für Eure Taten nicht besser Ausdruck verleihen, als wenn wir Euch den Mantel des Wildfangs überreichen würden!", sourceObjectiveStatus = "unverified-source-field" }
quests[8073] = { id = 8073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Die Tunika des Wildfangs", description = "Meine Augen haben mich schon seit langem im Stich gelassen, aber ich trauere ihnen nicht nach. Selbst in einem Stamm wie dem unsrigen, in dem die Kleidung Rang und Bestimmung vermittelt, strahlen die einflussreichsten aller Gewänder eine Macht aus, die für normale Augen nicht sichtbar ist. Die Tunika des Zandalariwildfangs ist keine Ausnahme, sie strahlt die rohe Macht des Chaos und des Wahnsinns aus, die mit ihr kanalisiert werden kann.\n\nDie Symbole der Macht, die ich benötige, befinden sich in Zul'Gurub; bringt mir eines und ich werde Euch mit Eurer eigenen legendären Tunika belohnen... eine, die einem Säer des Wahnsinns gerecht wird.", sourceObjective = "Bringt eine urzeitliche Aegis der Hakkari zu Falthir dem Blinden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Nochmals willkommen auf der Insel, {name}... seid Ihr triumphierend mit dem Symbol der Macht zurückgekehrt?", completion = "Beeindruckend... Ihr habt heute vollbracht, was kaum für möglich gehalten wurde. Ihr könnt Euch dem Respekt unseres Stammes auf Lebenszeit sicher sein, {name}. Nehmt die Tunika des Wildfangs entgegen, Ihr habt sie Euch verdient. Ihr habt unseren Segen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8074] = { id = 8074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Der Gürtel des Weissagers", description = "Die Weissager kennen das Mojo der Elemente, das ist wahr. Sie setzen es ein, um den Stamm zu Ruhm und Ehre zu führen. In den dunklen Zeiten, nachdem das Imperium der Gurubashi sich selbst zersplitterte, führten uns unsere Weissager in den sicheren Hafen der südlichen See. Sie haben uns auch wieder zurück hierher ins Tal geführt, genau ins Herz des Bösen, das in Zul'Gurub schwelt.\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und beweist Euch als uns würdig. Solltet Ihr dabei Erfolg haben, werde ich Euch einen Gürtel geben, wie ihn unsere Weissager verwenden, einen mit mächtigem Mojo!", sourceObjective = "Bringt einen urzeitlichen Hakkarigurt zu Maywiki von Zuldazar. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nMaywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Das Symbol der Macht ist genau das, was wir brauchen, Mann. Wir werden ihm die Macht während unseres Kampfes gegen das Böse von Zul'Gurub entreißen. Habt Ihr es bei Euch?", completion = "Ich kann den Sieg über das Böse wittern, {name}. Es ist ein süßer Duft... einer, der Euch sicherlich vertraut ist.\n\nIch weiß, dass die Beschaffung des Symbols, das für den Gürtel benötigt wird, nicht gerade einfach war. Eure Taten haben nicht nur unseren Stamm, sondern auch Euch selbst zu Ehren gebracht. Hier - nehmt den Gürtel des Weissagers und macht weiter so!", sourceObjectiveStatus = "unverified-source-field" }
quests[8075] = { id = 8075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Die Halsberge des Weissagers", description = "Die Weissager der Zandalari tragen einen bestimmten Brustschmuck, der Halsberge genannt wird. Er wird aus feinster Seide und Stoffen zusammengefügt und mit starken Ketten verwoben. Es ist nicht nur ein Symbol für ihre Göttlichkeit, sondern auch für ihre Autorität. Es ist niemals sehr weise den Weg von jemanden zu kreuzen, der sein Leben der Zwiesprache mit den Geistern gewidmet hat...\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und beweist Euch als uns würdig. Solltet Ihr dabei Erfolg haben, werde ich Euch eine der feinsten Halsbergen geben, die sich selbst einer der unsrigen Weissager zu tragen erhofft!", sourceObjective = "Bringt einen urzeitlichen Hakkariwappenrock zu Maywiki von Zuldazar. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nMaywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Die Symbole der Macht sind die ausschlaggebende Quelle magischer Macht... die gleiche Art Macht, die in die Herstellung der Halsberge des Weissagers einfließt. Bringt mir was ich brauche und ich werde Euch ein Bekleidungsstück geben, das selbst ein Weissager der Zandalar noch begehrt.", completion = "Ich weiß, was Ihr durchgemacht habt, um mir das Symbol der Macht zu beschaffen, {name}. Es war nicht einfach das Böse zu bezwingen, das aus Zul'Gurub wie fauler Schlick sickert, ja - jetzt, nachdem alles gesagt und getan ist, kann ich Euch jedoch als im Stamm der Zandalar respektiert bezeichnen - und das für Lebzeiten!\n\nHier - nehmt die Halsberge des Weissagers und tragt sie mit Stolz!", sourceObjectiveStatus = "unverified-source-field" }
quests[8076] = { id = 8076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Der Mantel des Besessenen", description = "Der Besessene möchte Macht geradewegs verkörpern und nicht nur besitzen. Mehr als ein Besessener hat bereits den Kampf gegen einen Dämonen verloren; die Feinde, die uns bedrohen, besonders in Zul'Gurub, und die Macht, die ein Besessener auf unsere Feinde loslassen kann, sind das Opfer jedoch wert. Unser Überleben hängt von der Zerstörung derer ab, die nach unserem Ende trachten; das hat uns der Fall des Imperiums der Gurubashi gelehrt.\n\nReist nach Zul'Gurub und beschafft uns das von uns benötigte Symbol der Macht. Solltet Ihr dabei Erfolg haben, soll ein wertvoller Gegenstand eines Besessenen Euer Eigen sein.", sourceObjective = "Bringt eine urzeitliche Hakkarischärpe zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Habt Ihr das Symbol der Macht von Zul'Gurub beschafft? Wenn wir diesem Gegenstand die latente Macht entnehmen und zu unserem Eigen machen, werden wir Euch Eure eigene Belohnung der Macht aushändigen... solltet Ihr erfolgreich gewesen sein...", completion = "Gut gemacht, {name}. Die Symbole der Macht von Zul'Gurub sollten als Beweis für verschwendete Macht dienen. Die Gurubashi waren zu ihren Hochzeiten stark, aber sie gestatteten sich selbst davon aufgezehrt zu werden. Der Besessene weiß, dass die Spiele, die von ihm gespielt werden, ähnlich sind, jedoch ist die Macht, die dabei freigegeben wird, oft das Ausschlaggebende zum Überleben.\n\nVerwendet diesen Mantel als jemand, der von den Zandalar mit Wohlwollen als Verbündeter betrachtet wird... er wird Euch noch nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[8077] = { id = 8077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Die Roben des Besessenen", description = "Im Stamm ist das ultimative Zeichen für Macht die Kleidung, die im Kampf getragen wird. Die Roben des Besessenen vereinen feinen Runenstoff und verheerend mächtiges Mojo. Man sagt, dass das Aussehen dieser Roben allen Angst einflößt, die sie erblicken... besonders den Dämonen, die der Besessene eventuell beherrschen möchte.\n\nIhr müsst mir von Zul'Gurub ein besonderes Symbol der Macht besorgen. Es wird nicht einfach sein... Euer erfolgreiches Handeln wird Euch jedoch den Besitz einer der besagten Roben sichern.", sourceObjective = "Bringt einen urzeitlichen Hakkarikosak zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Das Symbol der Macht... habt Ihr es bei Euch? Erst wenn wir es haben, werden wir das ultimative Zeichen besessener Macht mit Euch teilen, {name}.", completion = "Beeindruckend - Euer Sieg in Zul'Gurub hat uns bewiesen - ach, was sage ich denn da, der ganzen Welt - dass Hakkar sich nicht durchsetzen wird. Die Zeit, in der Ihr dem Blutgott direkt gegenüberstehen werdet, wird noch kommen... sollte es soweit sein, dann wisst, dass Euch der Respekt der Zandalar sicher ist.\n\nOh, ich denke Euch wird auch diese einfache Robe behilflich sein.\n\n<Al'tabim zwinkert Euch wissend zu.>", sourceObjectiveStatus = "unverified-source-field" }
quests[8078] = { id = 8078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht: Der Gürtel des Vollstreckers", description = "Die ultimative Rache wartet innerhalb Zul'Gurubs. Hakkar darf nicht mehr auferstehen. Hakkar hat das Imperium der Gurubashi von innen heraus zerstört. Kein Opfer war ihm dafür zu schade. Die Trolle sind nur noch ein Schatten ihrer glorreichen Zeiten. Ich weiß, dass all dies auf Hakkar beruht.\n\nWerdet der Vollstrecker, zu dem Ihr bestimmt wart. Bringt Zerstörung über die Diener des Bösen herein. Zul'Gurub muss den Rachedurst der Zandalari zu spüren bekommen. Bringt mir ein Symbol der Macht als Beweis. Ihr werdet dafür den Gürtel des Vollstreckers bekommen. Ihr werdet wahre Macht erhalten.\n\nUnd nun geht.", sourceObjective = "Bringt einen urzeitlichen Hakkarigurt zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", progress = "Habt Ihr das Symbol der Macht? Habt Ihr die Feinde des Stammes niedergestreckt? Hakkar muss den Zorn des Vollstreckers kennenlernen!", completion = "Der Weg des Vollstreckers ist Euch jetzt bekannt. Ihr habt dem Stamm und Euch selbst Ehre eingebracht und Schmerz unter unseren Feinden gesät.\n\nDer Gürtel des Vollstreckers ist jetzt Euer Eigen. Ihr werdet mit Sicherheit eins mit dem Weg des Vollstreckers werden.", sourceObjectiveStatus = "unverified-source-field" }
